property.value:
//Annotation[pmd-java:typeIs('org.springframework.context.annotation.ComponentScan')]
|
//Annotation[pmd-java:typeIs('org.springframework.boot.autoconfigure.SpringBootApplication')]
  [AnnotationMemberList/MemberValuePair[@Name = ('scanBasePackages', 'scanBasePackageClasses')]]

//ClassDeclaration[not(ModifierList/Annotation[pmd-java:typeIs('org.springframework.context.annotation.Configuration')])]
  /ModifierList/Annotation[pmd-java:typeIs('org.springframework.context.annotation.Profile')]
|
//MethodDeclaration[not(ModifierList/Annotation[pmd-java:typeIs('org.springframework.context.annotation.Bean')])]
  /ModifierList/Annotation[pmd-java:typeIs('org.springframework.context.annotation.Profile')]

let $onlyFrom := function($method, $callers) {
  let $uses := $method/parent::ClassBody//(MethodCall[*[1][self::ArgumentList or self::ThisExpression[not(*)]]]
      | MethodReference[*[1][self::ThisExpression[not(*)]]])[@MethodName = $method/@Name]
  return $method/@Visibility = 'private' and exists($uses)
    and (every $use in $uses satisfies exists($use/ancestor::* intersect $callers))
},
    $setupMethod := function($method) {
  let $body := $method/parent::ClassBody,
      $starts := ($body/ConstructorDeclaration, $body/Initializer, $body/FieldDeclaration,
        $body/MethodDeclaration[ModifierList/Annotation[pmd-java:typeIs('org.springframework.context.annotation.Bean')]]),
      $helpers := $body/MethodDeclaration[$onlyFrom(., $starts)]
  return exists($method intersect ($starts, $helpers, $body/MethodDeclaration[$onlyFrom(., ($starts, $helpers))]))
},
    $setup := function($node) {
  not($node/ancestor::MethodDeclaration)
  or $setupMethod($node/ancestor::MethodDeclaration[1])
  or $node/ancestor::MethodDeclaration[1][pmd-java:modifiers() = 'static']
    [exists($node/ancestor::ReturnStatement[ancestor::MethodDeclaration[1] is $node/ancestor::MethodDeclaration[1]])]
}
return (
  //ConstructorCall[pmd-java:typeIs('org.springframework.web.client.RestTemplate')
    or pmd-java:typeIs('org.springframework.boot.web.client.RestTemplateBuilder')
    or pmd-java:typeIs('org.springframework.boot.restclient.RestTemplateBuilder')]
  | //MethodCall[@MethodName = ('create', 'builder')]
      [*[1][self::TypeExpression and (pmd-java:typeIs('org.springframework.web.client.RestClient')
        or pmd-java:typeIs('org.springframework.web.reactive.function.client.WebClient'))]]
  | //MethodCall[@MethodName = ('newHttpClient', 'newBuilder')]
      [*[1][self::TypeExpression and pmd-java:typeIs('java.net.http.HttpClient')]]
)[not($setup(.))]

let $words := function($segment) {
  tokenize(lower-case(replace(replace(replace(string($segment), '\[\d+\]', ''),
    '([a-z\d])([A-Z])', '$1-$2'), '([A-Z])([A-Z][a-z])', '$1-$2')), '[-_]+')[. != '']
},
    $secret := function($key) {
  let $segments := tokenize(string($key), '\.'),
      $last := $words($segments[last()]),
      $owner := $words($segments[last() - 1])[last()],
      $names := ('password', 'passwd', 'passphrase', 'secret', 'token', 'credential', 'credentials', 'apikey', 'privatekey',
        'secretkey', 'accesskey', 'signingkey', 'encryptionkey', 'hmackey', 'jwtkey', 'cryptokey', 'masterkey')
  return $last[last()] = $names
    or (count($last) > 1 and string-join(subsequence($last, count($last) - 1), '') = $names)
    or (count($last) = 1 and $last = 'key'
      and $owner = ('api', 'jwt', 'encryption', 'signing', 'hmac', 'crypto', 'master', 'access', 'secret', 'private'))
},
    $fallback := function($value) {
  string-length($value) > 0 and not(matches($value, '^[#$]'))
}
return
//Annotation[pmd-java:typeIs('org.springframework.beans.factory.annotation.Value')]
  //StringLiteral[matches(@ConstValue, '^\$\{[^}:]+:[^}]*\}$')]
  [$secret(substring-before(substring-after(@ConstValue, '${'), ':'))]
  [$fallback(replace(@ConstValue, '^\$\{[^}:]+:(.*)\}$', '$1'))]
|
//Annotation[pmd-java:typeIs('org.springframework.boot.context.properties.bind.DefaultValue')]
  [$secret(../../VariableId/@Name)]
  [.//StringLiteral[$fallback(@ConstValue)]]
|
//MethodCall[@MethodName = 'getProperty'][*[1][pmd-java:typeIs('org.springframework.core.env.PropertyResolver')]]
  [ArgumentList[count(*) = 2]/*[1][self::StringLiteral][$secret(@ConstValue)]]
  [ArgumentList/*[2][self::StringLiteral][$fallback(@ConstValue)]]

//Annotation[pmd-java:typeIs('org.springframework.scheduling.annotation.Async')][not(AnnotationMemberList/MemberValuePair)]
|
//MethodDeclaration[ModifierList/Annotation[pmd-java:typeIs('org.springframework.scheduling.annotation.Async')]]
  [not(ClassType[pmd-java:typeIs('java.util.concurrent.CompletableFuture')])]

//ClassDeclaration[ModifierList/Annotation[pmd-java:typeIs('org.springframework.web.bind.annotation.RestController')]]
  //Annotation[pmd-java:typeIs('org.springframework.web.bind.annotation.ResponseBody')]
|
//ClassDeclaration[ModifierList/Annotation[pmd-java:typeIs('org.springframework.stereotype.Controller')]]
  /ModifierList/Annotation[pmd-java:typeIs('org.springframework.web.bind.annotation.ResponseBody')]

let $root := function($node) {
  let $statement := $node/ancestor::*[self::ExpressionStatement or self::ReturnStatement or self::LocalVariableDeclaration][last()],
      $chain := ($statement/VariableDeclarator/*[2], $statement/*[1])[1]
  return string(($chain/descendant-or-self::*[not(*)]
    [not(ancestor-or-self::*[exists(ancestor::*[. is $chain])][preceding-sibling::*])])[1]/@Name)
}
return (
//MethodCall[@MethodName = 'permitAll']
  [*[1][self::MethodCall[@MethodName = ('anyRequest', 'anyExchange')]
    or self::MethodCall[@MethodName = ('requestMatchers', 'antMatchers', 'mvcMatchers', 'pathMatchers')]
         [ArgumentList/StringLiteral[@ConstValue = ('/**', '/*', '**')]]
         [not(ArgumentList/*[pmd-java:typeIs('org.springframework.http.HttpMethod')])]]]
  [let $chain := $root(.)
   return not(ancestor::MethodDeclaration[1]//MethodCall[@MethodName = ('securityMatcher', 'securityMatchers')][$root(.) = $chain])]
|
//MethodCall[@MethodName = ('requestMatchers', 'antMatchers', 'mvcMatchers')]
  [*[1][self::MethodCall[@MethodName = 'ignoring']]]
  [ArgumentList/StringLiteral[@ConstValue = ('/**', '/*', '**')]]
)

let $root := function($node) {
  let $statement := $node/ancestor::*[self::ExpressionStatement or self::ReturnStatement or self::LocalVariableDeclaration][last()],
      $chain := ($statement/VariableDeclarator/*[2], $statement/*[1])[1]
  return string(($chain/descendant-or-self::*[not(*)]
    [not(ancestor-or-self::*[exists(ancestor::*[. is $chain])][preceding-sibling::*])])[1]/@Name)
}
return (
  //MethodCall[@MethodName = 'csrf'][ArgumentList/LambdaExpression//MethodCall[@MethodName = 'disable']]
  | //MethodCall[@MethodName = 'csrf'][ArgumentList/MethodReference[@MethodName = 'disable']]
  | //MethodCall[@MethodName = 'disable'][*[1][self::MethodCall[@MethodName = 'csrf'][not(ArgumentList/*)]]]
)[let $chain := $root(.), $calls := ancestor::MethodDeclaration[1]//MethodCall[$root(.) = $chain]
  return not($calls[@MethodName = 'sessionCreationPolicy'][.//*[@Name = 'STATELESS']]
    or $calls[@MethodName = ('securityContext', 'securityContextRepository')][.//*[
      pmd-java:typeIs('org.springframework.security.web.context.NullSecurityContextRepository')
      or pmd-java:typeIs('org.springframework.security.web.server.context.NoOpServerSecurityContextRepository')]]
    or ($calls[@MethodName = 'oauth2ResourceServer'][.//(MethodCall | MethodReference)[@MethodName = ('jwt', 'opaqueToken')]]
        and not($calls[@MethodName = ('formLogin', 'httpBasic', 'rememberMe', 'oauth2Login', 'saml2Login')]
          [not(ArgumentList/MethodReference[@MethodName = 'disable']
            or ArgumentList/LambdaExpression[.//MethodCall[@MethodName = 'disable']]
            or parent::MethodCall[@MethodName = 'disable'])])))]

//Annotation[(pmd-java:typeIs('jakarta.persistence.ManyToOne') or pmd-java:typeIs('javax.persistence.ManyToOne')) or (pmd-java:typeIs('jakarta.persistence.OneToOne') or pmd-java:typeIs('javax.persistence.OneToOne'))]
  [not(AnnotationMemberList/MemberValuePair[@Name = 'fetch'][.//*[@Name = 'LAZY']])]
|
//Annotation[(pmd-java:typeIs('jakarta.persistence.OneToMany') or pmd-java:typeIs('javax.persistence.OneToMany')) or (pmd-java:typeIs('jakarta.persistence.ManyToMany') or pmd-java:typeIs('javax.persistence.ManyToMany'))
    or (pmd-java:typeIs('jakarta.persistence.ElementCollection') or pmd-java:typeIs('javax.persistence.ElementCollection'))]
  [AnnotationMemberList/MemberValuePair[@Name = 'fetch'][.//*[@Name = 'EAGER']]]

//FieldDeclaration[ModifierList/Annotation[(pmd-java:typeIs('jakarta.persistence.ManyToMany') or pmd-java:typeIs('javax.persistence.ManyToMany'))]]
  [not(ModifierList/Annotation[(pmd-java:typeIs('jakarta.persistence.OrderColumn') or pmd-java:typeIs('javax.persistence.OrderColumn'))])]
  /ClassType[pmd-java:typeIs('java.util.List') or pmd-java:typeIsExactly('java.util.Collection')]

//Annotation[pmd-java:typeIs('org.springframework.data.jpa.repository.NativeQuery')]
|
//Annotation[pmd-java:typeIs('org.springframework.data.jpa.repository.Query')]
  [AnnotationMemberList/MemberValuePair[@Name = 'nativeQuery']/BooleanLiteral[@True = true()]]
|
//MethodCall[@MethodName = 'createNativeQuery'][*[1][(pmd-java:typeIs('jakarta.persistence.EntityManager') or pmd-java:typeIs('javax.persistence.EntityManager'))]]

//Annotation[pmd-java:typeIs('org.springframework.data.jpa.repository.Modifying')]
  [not(AnnotationMemberList/MemberValuePair[@Name = 'clearAutomatically']/BooleanLiteral[@True = true()])
   or not(AnnotationMemberList/MemberValuePair[@Name = 'flushAutomatically']/BooleanLiteral[@True = true()])]

let $iterated := function($call) {
  exists($call/*[1][pmd-java:typeIs('java.util.stream.BaseStream') or pmd-java:typeIs('java.lang.Iterable')
    or pmd-java:typeIs('java.util.Map') or pmd-java:typeIs('java.util.Iterator')])
},
    $loop := function($node) {
  exists($node/ancestor::*[self::ForStatement or self::ForeachStatement or self::WhileStatement or self::DoStatement]
    [not(.//IfStatement[*[1]//InfixExpression[@Operator = '%']]//MethodCall[@MethodName = 'clear'][*[1][(pmd-java:typeIs('jakarta.persistence.EntityManager') or pmd-java:typeIs('javax.persistence.EntityManager'))]])])
  or exists($node/ancestor::LambdaExpression[parent::ArgumentList/parent::MethodCall
    [@MethodName = ('forEach', 'forEachOrdered', 'forEachRemaining', 'map', 'peek', 'flatMap', 'mapToObj')][$iterated(.)]])
},
    $entityWrite := function($node) {
  $node/@MethodName = ('save', 'saveAndFlush', 'delete', 'deleteById', 'persist', 'merge', 'remove')
  and exists($node/*[1][pmd-java:typeIs('org.springframework.data.repository.Repository')
    or (pmd-java:typeIs('jakarta.persistence.EntityManager') or pmd-java:typeIs('javax.persistence.EntityManager'))])
}
return
//MethodCall[$entityWrite(.)][$loop(.)]
|
//MethodCall[@MethodName = ('forEach', 'forEachOrdered', 'forEachRemaining', 'map', 'peek')][$iterated(.)]
  /ArgumentList/MethodReference[$entityWrite(.)]
|
//VariableDeclarator[let $name := VariableId/@Name
    return ancestor::MethodDeclaration[1]//(MethodCall[@MethodName = 'accept'][*[1][self::VariableAccess[@Name = $name]]][$loop(.)]
      | MethodCall[@MethodName = ('forEach', 'forEachOrdered', 'forEachRemaining', 'map', 'peek')][$iterated(.)]
          /ArgumentList/VariableAccess[@Name = $name])]
  /MethodReference[$entityWrite(.)]

//Annotation[pmd-java:typeIs('org.springframework.data.jpa.repository.Query')
    or pmd-java:typeIs('org.springframework.data.jpa.repository.NativeQuery')]
  //StringLiteral[matches(@ConstValue, '\?[0-9]')]

//Annotation[pmd-java:typeIs('org.springframework.data.jpa.repository.Query')
    or pmd-java:typeIs('org.springframework.data.jpa.repository.NativeQuery')]
  /AnnotationMemberList/MemberValuePair[@Name = ('value', 'countQuery')]/InfixExpression[@Operator = '+']
